WITH oracle_1 AS (SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS b INNER JOIN `newzl`.`hsj_stock_code_info` AS s ON s.mktcode=b.mktcode AND s.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14' AND b.volume > 100 AND s.stFlag = FALSE), branch_1 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_1 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode IN (0,1) AND q.volume>=10), oracle_2 AS (WITH ranked AS (SELECT b.mktcode,b.tgtcode,b.bizdate,ROW_NUMBER() OVER (ORDER BY b.volume DESC,b.mktcode ASC,b.tgtcode ASC) AS rn,COUNT(*) OVER () AS population FROM `newzl`.`hsj_stock_hq_basic` AS b WHERE b.bizdate='2026-04-14') SELECT mktcode,tgtcode,bizdate FROM ranked WHERE rn<=10), branch_2 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_2 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=1 AND q.volume>=1000), oracle_3 AS (WITH benchmark AS (SELECT b.volume FROM `newzl`.`hsj_stock_hq_basic` AS b INNER JOIN `newzl`.`hsj_stock_code_info` AS s ON s.mktcode=b.mktcode AND s.tgtcode=b.tgtcode WHERE s.name='贵州茅台' AND b.bizdate='2026-04-14') SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS b CROSS JOIN benchmark AS q WHERE b.mktcode=1 AND b.bizdate='2026-04-14' AND b.volume>q.volume), branch_3 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_3 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode IN (0,1) AND q.volume>=1), nested_pair AS (SELECT l.mktcode,l.tgtcode,l.bizdate FROM branch_1 l INNER JOIN branch_2 r ON r.mktcode=l.mktcode AND r.tgtcode=l.tgtcode AND r.bizdate=l.bizdate) SELECT mktcode,tgtcode,bizdate FROM nested_pair UNION DISTINCT SELECT mktcode,tgtcode,bizdate FROM branch_3;
